import { type FC, useMemo } from 'react';

import BigNumber from 'bignumber.js';
import { useIntl } from 'react-intl';

import {
  type IYStackProps,
  IconButton,
  SizableText,
  XStack,
  YStack,
  useMedia,
} from '@onekeyhq/components';
import { Currency } from '@onekeyhq/kit/src/components/Currency';
import { RewardSummaryCard } from '@onekeyhq/kit/src/views/ReferFriends/components/RewardSummaryCard';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import platformEnv from '@onekeyhq/shared/src/platformEnv';

const MIN_DISPLAY_AMOUNT = 0.01;

interface IUndistributedRewardCardProps extends IYStackProps {
  value: string | number;
  showIcon?: boolean;
  onIconPress?: () => void;
}

export const UndistributedRewardCard: FC<IUndistributedRewardCardProps> = ({
  value,
  showIcon = false,
  onIconPress,
  ...rest
}) => {
  const intl = useIntl();
  const { md } = useMedia();

  const isMinDisplay = useMemo(() => {
    const bn = new BigNumber(value);
    return bn.isGreaterThan(0) && bn.isLessThan(MIN_DISPLAY_AMOUNT);
  }, [value]);

  if (md) {
    // Same summary card as the other reward pages on compact layouts.
    return (
      <YStack testID="UndistributedRewardCard" {...rest}>
        <RewardSummaryCard
          title={intl.formatMessage({
            id: ETranslations.referral_undistributed,
          })}
          value={String(value)}
          valueText={isMinDisplay ? `< $${MIN_DISPLAY_AMOUNT}` : undefined}
        />
      </YStack>
    );
  }

  return (
    <YStack gap="$1" testID="UndistributedRewardCard" {...rest}>
      <XStack
        ai="center"
        jc="space-between"
        gap="$2"
        pt={platformEnv.isNative ? '$10' : undefined}
      >
        <SizableText size="$bodyLg" color="$textSubdued">
          {intl.formatMessage({
            id: ETranslations.referral_undistributed,
          })}
        </SizableText>
        {showIcon ? (
          <IconButton
            testID="refer-friends-bn-icon-btn"
            icon="InfoCircleOutline"
            variant="tertiary"
            size="small"
            iconProps={{ color: '$iconSubdued' }}
            onPress={onIconPress}
          />
        ) : null}
      </XStack>
      {isMinDisplay ? (
        <SizableText size="$heading4xl">{`< $${MIN_DISPLAY_AMOUNT}`}</SizableText>
      ) : (
        <Currency formatter="value" size="$heading4xl">
          {value}
        </Currency>
      )}
    </YStack>
  );
};
